import { test } from "node:test";
import assert from "node:assert/strict";
import { canShip } from "../src/deploy.ts";

test("allows deploys before 16:00 Berlin time on regular days", () => {
  // 2026-11-10 at 10:00 Berlin time (Tuesday, mid-month)
  const date = new Date("2026-11-10T09:00:00Z"); // 10:00 Berlin (CET = UTC+1)
  assert.equal(canShip(date), true);
});

test("blocks deploys at 16:00 Berlin time", () => {
  // 2026-11-10 at 16:00 Berlin time
  const date = new Date("2026-11-10T15:00:00Z"); // 16:00 Berlin (CET = UTC+1)
  assert.equal(canShip(date), false);
});

test("blocks deploys after 16:00 Berlin time", () => {
  // 2026-11-10 at 18:30 Berlin time
  const date = new Date("2026-11-10T17:30:00Z"); // 18:30 Berlin (CET = UTC+1)
  assert.equal(canShip(date), false);
});

test("blocks deploys on the last working day of the month", () => {
  // November 2026 ends on Monday 30th
  // Last working day is Monday, Nov 30
  const date = new Date("2026-11-30T10:00:00Z"); // 11:00 Berlin, last working day
  assert.equal(canShip(date), false);
});

test("blocks deploys on the second-to-last working day of the month", () => {
  // November 2026: 30th (Mon) is last working day, 27th (Fri) is second-to-last
  const date = new Date("2026-11-27T10:00:00Z"); // 11:00 Berlin, Nov 27 (Friday)
  assert.equal(canShip(date), false);
});

test("allows deploys on the third-to-last working day", () => {
  // November 2026: 26th (Thu) is third-to-last working day
  const date = new Date("2026-11-26T10:00:00Z"); // 11:00 Berlin, Nov 26 (Thursday)
  assert.equal(canShip(date), true);
});

test("allows deploys on weekends near month end", () => {
  // November 2026: 28th and 29th are Saturday and Sunday
  const saturday = new Date("2026-11-28T10:00:00Z");
  const sunday = new Date("2026-11-29T10:00:00Z");
  assert.equal(canShip(saturday), true);
  assert.equal(canShip(sunday), true);
});

test("handles month ending on Friday correctly", () => {
  // October 2026 ends on Saturday the 31st
  // Last working day is Friday Oct 30, second-to-last is Thursday Oct 29
  const friday = new Date("2026-10-30T10:00:00Z"); // Last working day
  const thursday = new Date("2026-10-29T10:00:00Z"); // Second-to-last working day
  const wednesday = new Date("2026-10-28T10:00:00Z"); // Third-to-last working day

  assert.equal(canShip(friday), false);
  assert.equal(canShip(thursday), false);
  assert.equal(canShip(wednesday), true);
});

test("handles month ending on weekend correctly", () => {
  // August 2026 ends on Monday the 31st
  // 29th (Sat), 30th (Sun) are weekend
  // Last working day is Monday Aug 31, second-to-last is Friday Aug 28
  const monday = new Date("2026-08-31T10:00:00Z"); // Last working day
  const friday = new Date("2026-08-28T10:00:00Z"); // Second-to-last working day
  const thursday = new Date("2026-08-27T10:00:00Z"); // Third-to-last working day

  assert.equal(canShip(monday), false);
  assert.equal(canShip(friday), false);
  assert.equal(canShip(thursday), true);
});

test("month-end freeze applies even before 16:00", () => {
  // Last working day but before cutoff time
  const date = new Date("2026-11-30T08:00:00Z"); // 09:00 Berlin, last working day
  assert.equal(canShip(date), false);
});

test("time cutoff applies even outside month-end freeze", () => {
  // Mid-month but after 16:00
  const date = new Date("2026-11-15T16:00:00Z"); // 17:00 Berlin, mid-month
  assert.equal(canShip(date), false);
});

test("handles DST transitions correctly", () => {
  // March 2026: DST starts March 29
  // Test before DST (CET = UTC+1)
  const beforeDST = new Date("2026-03-20T14:00:00Z"); // 15:00 Berlin
  assert.equal(canShip(beforeDST), true);

  // Test after DST starts (CEST = UTC+2)
  const afterDST = new Date("2026-03-30T13:00:00Z"); // 15:00 Berlin
  assert.equal(canShip(afterDST), true);
});

